// ---- common/cache_tb_defs.sv ----
package cache_tb_defs_pkg;

  localparam int unsigned DUT_ADDR_W     = 32;
  localparam int unsigned DUT_DATA_W     = 32;
  localparam int unsigned DUT_LINE_BYTES = 16;
  localparam int unsigned DUT_NUM_SETS   = 64;
  localparam int unsigned DUT_N_WAYS     = 4;
  localparam int unsigned DUT_ID_W       = 4;

  localparam int unsigned ADDR_W   = DUT_ADDR_W;
  localparam int unsigned DATA_W   = DUT_DATA_W;
  localparam int unsigned ID_W     = DUT_ID_W;
  localparam int unsigned STRB_W   = DATA_W / 8;
  localparam int unsigned LINE_W   = DUT_LINE_BYTES * 8;
  localparam int unsigned WPL      = DUT_LINE_BYTES / STRB_W;
  localparam int unsigned BYTE_W   = $clog2(STRB_W);
  localparam int unsigned OFF_W    = $clog2(DUT_LINE_BYTES);
  localparam int unsigned SET_W    = $clog2(DUT_NUM_SETS);

  localparam time CLK_PERIOD = 10ns;

  typedef bit [ADDR_W-1:0]  addr_t;
  typedef bit [DATA_W-1:0]  data_t;
  typedef bit [STRB_W-1:0]  strb_t;
  typedef bit [LINE_W-1:0]  line_t;
  typedef bit [ID_W-1:0]    id_t;

  typedef enum {OUT_HIT, OUT_CLEAN_MISS, OUT_DIRTY_MISS} outcome_e;

  function automatic byte unsigned init_byte(addr_t a);
    return byte'(a[7:0] ^ a[15:8] ^ a[23:16] ^ a[31:24] ^ 8'h5A) + byte'(a[3:0]);
  endfunction

  function automatic addr_t mk_addr(int unsigned tag, int unsigned set, int unsigned word = 0);
    addr_t a;
    a = (addr_t'(tag) << (SET_W + OFF_W))
      | (addr_t'(set % DUT_NUM_SETS) << OFF_W)
      | (addr_t'(word % WPL) << BYTE_W);
    return a;
  endfunction

  function automatic addr_t line_base(addr_t a);
    return a & ~addr_t'(DUT_LINE_BYTES - 1);
  endfunction

  function automatic string run_suffix();
    string id;
    if ($value$plusargs("RUN_ID=%s", id)) return {"_", id};
    return "";
  endfunction

endpackage

// ---- top/cache_if.sv ----

interface cache_cpu_if (input logic clk, input logic rst_n);

  import cache_tb_defs_pkg::*;

  logic                 req_valid = 1'b0;
  logic                 req_ready;
  logic [ID_W-1:0]      req_id    = '0;
  logic                 req_we    = 1'b0;
  logic [ADDR_W-1:0]    req_addr  = '0;
  logic [DATA_W-1:0]    req_wdata = '0;
  logic [STRB_W-1:0]    req_wstrb = '0;

  logic                 rsp_valid;
  logic                 rsp_ready = 1'b0;
  logic [ID_W-1:0]      rsp_id;
  logic                 rsp_we;
  logic [DATA_W-1:0]    rsp_rdata;
  logic                 rsp_err;

  logic                 flush_req = 1'b0;
  logic                 flush_inv = 1'b0;
  logic                 flush_busy;
  logic                 flush_done;
  logic                 flush_err;

  clocking drv_cb @(posedge clk);
    default input #1step output #1;
    output req_valid, req_id, req_we, req_addr, req_wdata, req_wstrb;
    output rsp_ready;
    input  req_ready;
    input  rsp_valid, rsp_id, rsp_we, rsp_rdata, rsp_err;
  endclocking

  clocking flush_cb @(posedge clk);
    default input #1step output #1;
    output flush_req, flush_inv;
    input  flush_busy, flush_done, flush_err;
  endclocking

  clocking mon_cb @(posedge clk);
    default input #1step;
    input req_valid, req_ready, req_id, req_we, req_addr, req_wdata, req_wstrb;
    input rsp_valid, rsp_ready, rsp_id, rsp_we, rsp_rdata, rsp_err;
    input flush_req, flush_inv, flush_busy, flush_done, flush_err;
  endclocking

endinterface

interface cache_mem_if (input logic clk, input logic rst_n);

  import cache_tb_defs_pkg::*;

  logic                 req_valid;
  logic                 req_ready = 1'b0;
  logic                 req_we;
  logic [ADDR_W-1:0]    req_addr;
  logic [LINE_W-1:0]    req_wdata;

  logic                 rsp_valid = 1'b0;
  logic                 rsp_ready;
  logic [LINE_W-1:0]    rsp_rdata = '0;
  logic                 rsp_err   = 1'b0;

  clocking drv_cb @(posedge clk);
    default input #1step output #1;
    output req_ready;
    output rsp_valid, rsp_rdata, rsp_err;
    input  req_valid, req_we, req_addr, req_wdata;
    input  rsp_ready;
  endclocking

  clocking mon_cb @(posedge clk);
    default input #1step;
    input req_valid, req_ready, req_we, req_addr, req_wdata;
    input rsp_valid, rsp_ready, rsp_rdata, rsp_err;
  endclocking

endinterface

