// ---- agents/mem_agent/mem_model.sv ----
class mem_model extends uvm_object;

  `uvm_object_utils(mem_model)

  byte unsigned mem [addr_t];

  function new(string name = "mem_model");
    super.new(name);
  endfunction

  function byte unsigned read_byte(addr_t a);
    return mem.exists(a) ? mem[a] : init_byte(a);
  endfunction

  function void write_byte(addr_t a, byte unsigned b);
    mem[a] = b;
  endfunction

  function line_t read_line(addr_t line_addr);
    line_t l;
    for (int i = 0; i < DUT_LINE_BYTES; i++)
      l[8*i +: 8] = read_byte(line_addr + i);
    return l;
  endfunction

  function void write_line(addr_t line_addr, line_t l);
    for (int i = 0; i < DUT_LINE_BYTES; i++)
      write_byte(line_addr + i, l[8*i +: 8]);
  endfunction

endclass
// ---- env/cache_ref_model.sv ----
class cache_ref_model extends uvm_object;

  `uvm_object_utils(cache_ref_model)

  byte unsigned ref_mem [addr_t];
  bit           unknown [addr_t];

  function new(string name = "cache_ref_model");
    super.new(name);
  endfunction

  function void apply_store(addr_t addr, data_t wdata, strb_t wstrb);
    for (int i = 0; i < STRB_W; i++) begin
      if (wstrb[i]) begin
        ref_mem[addr + i] = wdata[8*i +: 8];
        if (unknown.exists(addr + i)) unknown.delete(addr + i);
      end
    end
  endfunction

  function bit expected_byte(addr_t a, output byte unsigned val);
    if (unknown.exists(a)) begin
      val = 8'h00;
      return 1'b0;
    end
    val = ref_mem.exists(a) ? ref_mem[a] : init_byte(a);
    return 1'b1;
  endfunction

  function void expected_word(addr_t addr, output data_t data, output strb_t mask);
    byte unsigned b;
    data = '0;
    mask = '0;
    for (int i = 0; i < STRB_W; i++) begin
      mask[i]         = expected_byte(addr + i, b);
      data[8*i +: 8]  = b;
    end
  endfunction

  function void mark_line_unknown(addr_t line_addr);
    for (int i = 0; i < DUT_LINE_BYTES; i++)
      unknown[line_addr + i] = 1'b1;
  endfunction

  function int unsigned num_unknown();
    return unknown.num();
  endfunction

endclass
