// ---- agents/cpu_agent/cpu_drv.sv ----
class cpu_drv extends uvm_driver #(cpu_item);

  `uvm_component_utils(cpu_drv)

  cache_cfg              cfg;
  virtual cache_cpu_if   vif;

  cpu_item      inflight [id_t];
  int unsigned  outstanding;
  id_t          next_id;
  bit           rsp_ready_now;

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db #(cache_cfg)::get(this, "", "cfg", cfg))
      `uvm_fatal("CPU_DRV", "no cache_cfg in config_db")
    vif = cfg.cpu_vif;
  endfunction

  task run_phase(uvm_phase phase);
    wait (vif.rst_n === 1'b1);
    fork
      request_thread();
      response_thread();
    join
  endtask

  task request_thread();
    cpu_item req;
    forever begin
      seq_item_port.get(req);

      while (outstanding >= cfg.max_outstanding) @(vif.drv_cb);
      repeat ($urandom_range(0, cfg.cpu_gap_max)) @(vif.drv_cb);

      while (inflight.exists(next_id)) next_id++;
      req.id = next_id;
      next_id++;

      @(vif.drv_cb);
      vif.drv_cb.req_valid <= 1'b1;
      vif.drv_cb.req_id    <= req.id;
      vif.drv_cb.req_we    <= req.we;
      vif.drv_cb.req_addr  <= req.addr;
      vif.drv_cb.req_wdata <= req.wdata;
      vif.drv_cb.req_wstrb <= req.wstrb;

      do @(vif.drv_cb);
      while (vif.drv_cb.req_ready !== 1'b1);

      req.t_accept       = $time;
      inflight[req.id]   = req;
      outstanding++;
      vif.drv_cb.req_valid <= 1'b0;
      `uvm_info("CPU_DRV", {"accepted   ", req.convert2string()}, UVM_HIGH)
    end
  endtask

  task response_thread();
    cpu_item rsp;
    id_t     rid;
    @(vif.drv_cb);
    forever begin
      rsp_ready_now = ($urandom_range(1, 100) <= cfg.cpu_rsp_ready_pct);
      vif.drv_cb.rsp_ready <= rsp_ready_now;
      @(vif.drv_cb);

      if (vif.drv_cb.rsp_valid === 1'b1 && rsp_ready_now) begin
        rid = vif.drv_cb.rsp_id;
        if (!inflight.exists(rid)) begin
          `uvm_error("CPU_DRV", $sformatf("response with id %0d but no such request in flight", rid))
        end
        else begin
          rsp = inflight[rid];
          inflight.delete(rid);
          outstanding--;
          rsp.rdata      = vif.drv_cb.rsp_rdata;
          rsp.err        = vif.drv_cb.rsp_err;
          rsp.rsp_we     = vif.drv_cb.rsp_we;
          rsp.t_rsp      = $time;
          rsp.lat_cycles = (rsp.t_rsp - rsp.t_accept) / CLK_PERIOD;
          `uvm_info("CPU_DRV", {"answered   ", rsp.convert2string()}, UVM_HIGH)
          seq_item_port.put(rsp);
        end
      end
    end
  endtask

endclass
// ---- agents/cpu_agent/cpu_mon.sv ----
class cpu_mon extends uvm_monitor;

  `uvm_component_utils(cpu_mon)

  uvm_analysis_port #(cpu_item)  ap;
  uvm_analysis_port #(cpu_item)  req_ap;

  cache_cfg              cfg;
  virtual cache_cpu_if   vif;

  cpu_item  pending [id_t];
  bit       reported_hang [id_t];

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    ap     = new("ap", this);
    req_ap = new("req_ap", this);
    if (!uvm_config_db #(cache_cfg)::get(this, "", "cfg", cfg))
      `uvm_fatal("CPU_MON", "no cache_cfg in config_db")
    vif = cfg.cpu_vif;
  endfunction

  task run_phase(uvm_phase phase);
    cpu_item t;
    id_t     rid;
    wait (vif.rst_n === 1'b1);
    forever begin
      @(vif.mon_cb);

      if (vif.mon_cb.rsp_valid === 1'b1) begin
        rid = vif.mon_cb.rsp_id;
        if (vif.mon_cb.rsp_ready === 1'b1) begin
          if (!pending.exists(rid)) begin
            `uvm_error("CPU_MON", $sformatf("response id %0d with no request in flight", rid))
          end
          else begin
            t = pending[rid];
            pending.delete(rid);
            if (reported_hang.exists(rid)) reported_hang.delete(rid);
            t.rdata      = vif.mon_cb.rsp_rdata;
            t.err        = vif.mon_cb.rsp_err;
            t.rsp_we     = vif.mon_cb.rsp_we;
            t.t_rsp      = $time;
            t.lat_cycles = (t.t_rsp - t.t_accept) / CLK_PERIOD;
            `uvm_info("CPU_MON", {"done       ", t.convert2string()}, UVM_HIGH)
            ap.write(t);
          end
        end
        else if (pending.exists(rid)) begin
          pending[rid].rsp_bp_cycles++;
        end
      end

      if (vif.mon_cb.req_valid === 1'b1 && vif.mon_cb.req_ready === 1'b1) begin
        t = cpu_item::type_id::create("cpu_mon_item");
        t.id       = vif.mon_cb.req_id;
        t.we       = vif.mon_cb.req_we;
        t.addr     = vif.mon_cb.req_addr;
        t.wdata    = vif.mon_cb.req_wdata;
        t.wstrb    = vif.mon_cb.req_wstrb;
        t.t_accept = $time;
        if (pending.exists(t.id))
          `uvm_error("CPU_MON", $sformatf("id %0d re-used while still in flight", t.id))
        pending[t.id] = t;
        req_ap.write(t);
      end

      foreach (pending[i]) begin
        if (!reported_hang.exists(i) &&
            ($time - pending[i].t_accept) > cfg.rsp_timeout * CLK_PERIOD) begin
          `uvm_error("CPU_MON", $sformatf("no response after %0d cycles: %s",
                                          cfg.rsp_timeout, pending[i].convert2string()))
          reported_hang[i] = 1'b1;
        end
      end
    end
  endtask

  function void check_phase(uvm_phase phase);
    super.check_phase(phase);
    if (pending.num() != 0)
      `uvm_error("CPU_MON", $sformatf("%0d request(s) never got a response", pending.num()))
  endfunction

endclass
// ---- agents/cpu_agent/cpu_agent.sv ----
class cpu_agent extends uvm_agent;

  `uvm_component_utils(cpu_agent)

  cpu_seqr   seqr;
  cpu_drv    drv;
  cpu_mon    mon;
  cache_cfg  cfg;

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db #(cache_cfg)::get(this, "", "cfg", cfg))
      `uvm_fatal("CPU_AGT", "no cache_cfg in config_db")
    seqr = cpu_seqr::type_id::create("seqr", this);
    drv  = cpu_drv::type_id::create("drv",  this);
    mon  = cpu_mon::type_id::create("mon",  this);
  endfunction

  function void connect_phase(uvm_phase phase);
    super.connect_phase(phase);
    drv.seq_item_port.connect(seqr.seq_item_export);
    seqr.cfg = cfg;
  endfunction

endclass

