// ---- agents/flush_agent/flush_drv.sv ----
class flush_drv extends uvm_driver #(flush_item);

  `uvm_component_utils(flush_drv)

  cache_cfg              cfg;
  virtual cache_cpu_if   vif;

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db #(cache_cfg)::get(this, "", "cfg", cfg))
      `uvm_fatal("FLUSH_DRV", "no cache_cfg in config_db")
    vif = cfg.cpu_vif;
  endfunction

  task run_phase(uvm_phase phase);
    flush_item req;
    wait (vif.rst_n === 1'b1);
    forever begin
      seq_item_port.get_next_item(req);

      @(vif.flush_cb);
      vif.flush_cb.flush_req <= 1'b1;
      vif.flush_cb.flush_inv <= req.inv;

      do @(vif.flush_cb);
      while (vif.flush_cb.flush_busy !== 1'b1);
      vif.flush_cb.flush_req <= 1'b0;

      do @(vif.flush_cb);
      while (vif.flush_cb.flush_done !== 1'b1);
      req.err = vif.flush_cb.flush_err;

      `uvm_info("FLUSH_DRV", $sformatf("finished   FLUSH inv=%0d err=%0d", req.inv, req.err), UVM_MEDIUM)
      seq_item_port.item_done();
    end
  endtask

endclass
// ---- agents/flush_agent/flush_mon.sv ----
class flush_mon extends uvm_monitor;

  `uvm_component_utils(flush_mon)

  uvm_analysis_port #(flush_item) ap;

  cache_cfg              cfg;
  virtual cache_cpu_if   vif;

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    ap = new("ap", this);
    if (!uvm_config_db #(cache_cfg)::get(this, "", "cfg", cfg))
      `uvm_fatal("FLUSH_MON", "no cache_cfg in config_db")
    vif = cfg.cpu_vif;
  endfunction

  task run_phase(uvm_phase phase);
    flush_item t;
    bit        prev_busy;
    bit        prev_cpu_waiting;
    wait (vif.rst_n === 1'b1);
    forever begin
      @(vif.mon_cb);

      if (vif.mon_cb.flush_busy === 1'b1 && !prev_busy) begin
        t         = flush_item::type_id::create("flush_mon_item");
        t.inv     = vif.mon_cb.flush_inv;
        t.race    = prev_cpu_waiting;
        t.t_start = $time;
      end

      if (t != null && vif.mon_cb.req_valid === 1'b1 && vif.mon_cb.req_ready !== 1'b1)
        t.race = 1'b1;

      if (vif.mon_cb.flush_done === 1'b1) begin
        if (t == null) begin
          `uvm_error("FLUSH_MON", "flush_done without a flush start")
        end
        else begin
          t.err    = vif.mon_cb.flush_err;
          t.t_done = $time;
          t.cycles = (t.t_done - t.t_start) / CLK_PERIOD;
          `uvm_info("FLUSH_MON", {"done       ", t.convert2string()}, UVM_HIGH)
          ap.write(t);
          t = null;
        end
      end

      prev_busy        = (vif.mon_cb.flush_busy === 1'b1);
      prev_cpu_waiting = (vif.mon_cb.req_valid === 1'b1) && (vif.mon_cb.req_ready !== 1'b1);
    end
  endtask

endclass
// ---- agents/flush_agent/flush_agent.sv ----
