// ---- agents/mem_agent/mem_drv.sv ----
class mem_drv extends uvm_driver #(mem_item);

  `uvm_component_utils(mem_drv)

  cache_cfg              cfg;
  virtual cache_mem_if   vif;

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db #(cache_cfg)::get(this, "", "cfg", cfg))
      `uvm_fatal("MEM_DRV", "no cache_cfg in config_db")
    vif = cfg.mem_vif;
  endfunction

  task run_phase(uvm_phase phase);
    wait (vif.rst_n === 1'b1);
    fork
      ready_thread();
      response_thread();
    join
  endtask

  task ready_thread();
    forever begin
      @(vif.drv_cb);
      vif.drv_cb.req_ready <= ($urandom_range(1, 100) <= cfg.mem_req_ready_pct);
    end
  endtask

  task response_thread();
    mem_item rsp;
    forever begin
      seq_item_port.get_next_item(rsp);

      repeat (rsp.latency + 1) @(vif.drv_cb);

      vif.drv_cb.rsp_valid <= 1'b1;
      vif.drv_cb.rsp_rdata <= rsp.rdata;
      vif.drv_cb.rsp_err   <= rsp.err;

      do @(vif.drv_cb);
      while (vif.drv_cb.rsp_ready !== 1'b1);

      vif.drv_cb.rsp_valid <= 1'b0;
      vif.drv_cb.rsp_err   <= 1'b0;
      `uvm_info("MEM_DRV", {"answered   ", rsp.convert2string()}, UVM_HIGH)
      seq_item_port.item_done();
    end
  endtask

endclass
// ---- agents/mem_agent/mem_mon.sv ----
class mem_mon extends uvm_monitor;

  `uvm_component_utils(mem_mon)

  uvm_analysis_port #(mem_item)  req_ap;
  uvm_analysis_port #(mem_item)  ap;

  cache_cfg              cfg;
  virtual cache_mem_if   vif;

  mem_item      pend_q[$];
  int unsigned  bp_count;

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    req_ap = new("req_ap", this);
    ap     = new("ap", this);
    if (!uvm_config_db #(cache_cfg)::get(this, "", "cfg", cfg))
      `uvm_fatal("MEM_MON", "no cache_cfg in config_db")
    vif = cfg.mem_vif;
  endfunction

  task run_phase(uvm_phase phase);
    mem_item t;
    mem_item c;
    wait (vif.rst_n === 1'b1);
    forever begin
      @(vif.mon_cb);

      if (vif.mon_cb.rsp_valid === 1'b1 && vif.mon_cb.rsp_ready === 1'b1) begin
        if (pend_q.size() == 0) begin
          `uvm_error("MEM_MON", "memory response with no request outstanding")
        end
        else begin
          t            = pend_q.pop_front();
          t.rdata      = vif.mon_cb.rsp_rdata;
          t.err        = vif.mon_cb.rsp_err;
          t.t_rsp      = $time;
          t.lat_cycles = (t.t_rsp - t.t_req) / CLK_PERIOD;
          `uvm_info("MEM_MON", {"done       ", t.convert2string()}, UVM_HIGH)
          ap.write(t);
        end
      end

      if (vif.mon_cb.req_valid === 1'b1) begin
        if (vif.mon_cb.req_ready === 1'b1) begin
          t               = mem_item::type_id::create("mem_mon_item");
          t.we            = vif.mon_cb.req_we;
          t.addr          = vif.mon_cb.req_addr;
          t.wdata         = vif.mon_cb.req_wdata;
          t.t_req         = $time;
          t.req_bp_cycles = bp_count;
          bp_count        = 0;
          pend_q.push_back(t);
          $cast(c, t.clone());
          req_ap.write(c);
        end
        else begin
          bp_count++;
        end
      end
    end
  endtask

  function void check_phase(uvm_phase phase);
    super.check_phase(phase);
    if (pend_q.size() != 0)
      `uvm_error("MEM_MON", $sformatf("%0d memory request(s) never answered", pend_q.size()))
  endfunction

endclass
// ---- agents/mem_agent/mem_resp_seq.sv ----
class mem_resp_seq extends uvm_sequence #(mem_item);

  `uvm_object_utils(mem_resp_seq)
  `uvm_declare_p_sequencer(mem_seqr)

  function new(string name = "mem_resp_seq");
    super.new(name);
  endfunction

  task body();
    mem_item   dut_req;
    mem_item   rsp;
    cache_cfg  cfg;
    cfg = p_sequencer.cfg;

    forever begin
      p_sequencer.dut_req_fifo.get(dut_req);

      rsp       = mem_item::type_id::create("mem_rsp");
      rsp.we    = dut_req.we;
      rsp.addr  = dut_req.addr;
      rsp.wdata = dut_req.wdata;

      rsp.latency = $urandom_range(cfg.mem_lat_min, cfg.mem_lat_max);
      if (dut_req.we) begin
        if (cfg.force_wr_err > 0) begin rsp.err = 1'b1; cfg.force_wr_err--; end
        else rsp.err = ($urandom_range(1, 100) <= cfg.mem_wr_err_pct);
      end
      else begin
        if (cfg.force_rd_err > 0) begin rsp.err = 1'b1; cfg.force_rd_err--; end
        else rsp.err = ($urandom_range(1, 100) <= cfg.mem_rd_err_pct);
      end

      if (rsp.err)          rsp.rdata = {(LINE_W/32){32'hBAD0_BAD0}};
      else if (dut_req.we)  cfg.mem.write_line(dut_req.addr, dut_req.wdata);
      else                  rsp.rdata = cfg.mem.read_line(dut_req.addr);

      `uvm_info("MEM_SEQ", $sformatf("%s addr=%h -> err=%0d latency=%0d",
                dut_req.we ? "WRITEBACK" : "REFILL", dut_req.addr, rsp.err, rsp.latency), UVM_HIGH)

      start_item(rsp);
      finish_item(rsp);
    end
  endtask

endclass
