// ---- env/cache_scoreboard.sv ----
`uvm_analysis_imp_decl(_sb_cpu)
`uvm_analysis_imp_decl(_sb_mem)
`uvm_analysis_imp_decl(_sb_flush)

class cache_scoreboard extends uvm_scoreboard;

  `uvm_component_utils(cache_scoreboard)

  uvm_analysis_imp_sb_cpu   #(cpu_item,   cache_scoreboard) cpu_imp;
  uvm_analysis_imp_sb_mem   #(mem_item,   cache_scoreboard) mem_imp;
  uvm_analysis_imp_sb_flush #(flush_item, cache_scoreboard) flush_imp;
  uvm_analysis_port         #(cpu_item)                     cov_ap;

  cache_cfg        cfg;
  cache_ref_model  ref_m;

  mem_item         mem_hist[$];

  int unsigned n_loads, n_stores, n_hits, n_clean_miss, n_dirty_miss;
  int unsigned n_mem_rd, n_mem_wr, n_mem_rd_err, n_mem_wr_err;
  int unsigned n_rsp_err, n_data_checked, n_data_skipped, n_mismatch;
  int unsigned n_flush, n_flush_err, n_mem_checks, n_mem_bytes_checked, n_mem_byte_bad;

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    cpu_imp   = new("cpu_imp",   this);
    mem_imp   = new("mem_imp",   this);
    flush_imp = new("flush_imp", this);
    cov_ap    = new("cov_ap",    this);
    ref_m     = cache_ref_model::type_id::create("ref_m");
    if (!uvm_config_db #(cache_cfg)::get(this, "", "cfg", cfg))
      `uvm_fatal("SB", "no cache_cfg in config_db")
  endfunction

  function void write_sb_mem(mem_item t);
    mem_hist.push_back(t);
    if (t.we) begin
      n_mem_wr++;
      if (t.err) begin
        n_mem_wr_err++;
        ref_m.mark_line_unknown(t.addr);
        `uvm_info("SB", $sformatf("writeback of line %h FAILED -> line now unchecked", t.addr), UVM_MEDIUM)
      end
    end
    else begin
      n_mem_rd++;
      if (t.err) n_mem_rd_err++;
    end
  endfunction

  function void write_sb_cpu(cpu_item t);
    int unsigned n_rd, n_wr;
    bit          rd_err, wr_err, exp_err;
    data_t       exp_data;
    strb_t       mask;
    mem_item     keep[$];

    foreach (mem_hist[i]) begin
      if (mem_hist[i].t_req > t.t_accept && mem_hist[i].t_rsp < t.t_rsp) begin
        if (mem_hist[i].we) begin
          n_wr++; wr_err |= mem_hist[i].err;
        end
        else begin
          n_rd++; rd_err |= mem_hist[i].err;
          if (mem_hist[i].addr !== line_base(t.addr))
            `uvm_error("SB", $sformatf("refill of line %h, but the access was to %h",
                                       mem_hist[i].addr, t.addr))
        end
      end
      else if (mem_hist[i].t_rsp > t.t_rsp) begin
        keep.push_back(mem_hist[i]);
      end
      else begin
        `uvm_error("SB", {"memory transaction outside any CPU access or flush: ",
                          mem_hist[i].convert2string()})
      end
    end
    mem_hist = keep;

    if (n_rd > 1 || n_wr > 1 || (n_wr == 1 && n_rd == 0))
      `uvm_error("SB", $sformatf("unexpected memory traffic for %s: %0d refill(s), %0d writeback(s)",
                                 t.convert2string(), n_rd, n_wr))

    if (n_rd == 0)      begin t.outcome = OUT_HIT;        n_hits++;       end
    else if (n_wr == 0) begin t.outcome = OUT_CLEAN_MISS; n_clean_miss++; end
    else                begin t.outcome = OUT_DIRTY_MISS; n_dirty_miss++; end

    exp_err = rd_err || wr_err;
    if (t.err) n_rsp_err++;
    if (t.err !== exp_err)
      `uvm_error("SB", $sformatf("err=%0d but expected %0d (refill err=%0d, writeback err=%0d): %s",
                                 t.err, exp_err, rd_err, wr_err, t.convert2string()))

    if (t.rsp_we !== t.we)
      `uvm_error("SB", $sformatf("rsp_we=%0d does not echo we=%0d: %s", t.rsp_we, t.we, t.convert2string()))

    if (t.we) begin
      n_stores++;
      if (!rd_err) ref_m.apply_store(t.addr, t.wdata, t.wstrb);
    end
    else begin
      n_loads++;
      if (rd_err) begin
        n_data_skipped++;
      end
      else begin
        ref_m.expected_word(t.addr, exp_data, mask);
        if (mask != '1) n_data_skipped++;
        if (mask != '0) begin
          n_data_checked++;
          for (int i = 0; i < STRB_W; i++) begin
            if (mask[i] && t.rdata[8*i +: 8] !== exp_data[8*i +: 8]) begin
              n_mismatch++;
              `uvm_error("SB", $sformatf("LOAD DATA MISMATCH addr=%h got=%h exp=%h (mask=%b) %s",
                                         t.addr, t.rdata, exp_data, mask, t.outcome.name()))
              break;
            end
          end
        end
      end
    end

    `uvm_info("SB", $sformatf("%s  %s", t.convert2string(), t.outcome.name()), UVM_HIGH)
    cov_ap.write(t);
  endfunction

  function void write_sb_flush(flush_item f);
    bit      wb_err;
    mem_item keep[$];

    n_flush++;
    foreach (mem_hist[i]) begin
      if (mem_hist[i].t_req >= f.t_start && mem_hist[i].t_rsp <= f.t_done) begin
        if (mem_hist[i].we) wb_err |= mem_hist[i].err;
      end
      else if (mem_hist[i].t_rsp > f.t_done) begin
        keep.push_back(mem_hist[i]);
      end
      else begin
        `uvm_error("SB", {"memory transaction outside any CPU access or flush: ",
                          mem_hist[i].convert2string()})
      end
    end
    mem_hist = keep;

    if (f.err) n_flush_err++;
    if (f.err !== wb_err)
      `uvm_error("SB", $sformatf("flush_err=%0d but a writeback error was %0sseen",
                                 f.err, wb_err ? "" : "NOT "))

    check_memory($sformatf("after flush #%0d (inv=%0d)", n_flush, f.inv));
  endfunction

  function void check_memory(string when);
    byte unsigned exp_b;
    int unsigned  checked, bad;

    n_mem_checks++;
    foreach (ref_m.ref_mem[a]) begin
      if (ref_m.expected_byte(a, exp_b)) begin
        checked++;
        if (cfg.mem.read_byte(a) !== exp_b) begin
          bad++;
          if (bad <= 5)
            `uvm_error("SB", $sformatf("MEMORY MISMATCH %s: addr=%h mem=%h exp=%h",
                                       when, a, cfg.mem.read_byte(a), exp_b))
        end
      end
    end
    foreach (cfg.mem.mem[a]) begin
      if (!ref_m.ref_mem.exists(a) && ref_m.expected_byte(a, exp_b)) begin
        checked++;
        if (cfg.mem.mem[a] !== exp_b) begin
          bad++;
          if (bad <= 5)
            `uvm_error("SB", $sformatf("MEMORY MISMATCH %s: addr=%h mem=%h exp=%h (never stored)",
                                       when, a, cfg.mem.mem[a], exp_b))
        end
      end
    end
    n_mem_bytes_checked += checked;
    n_mem_byte_bad      += bad;
    `uvm_info("SB", $sformatf("memory check %s: %0d bytes compared, %0d bad, %0d unknown skipped",
                              when, checked, bad, ref_m.num_unknown()), UVM_LOW)
  endfunction

  function string summary();
    return $sformatf({"loads=%0d stores=%0d | hits=%0d clean_miss=%0d dirty_miss=%0d | ",
                      "mem rd=%0d (err %0d) wr=%0d (err %0d) | rsp_err=%0d | ",
                      "data checked=%0d skipped=%0d MISMATCH=%0d | ",
                      "flushes=%0d (err %0d) mem checks=%0d bad bytes=%0d"},
                     n_loads, n_stores, n_hits, n_clean_miss, n_dirty_miss,
                     n_mem_rd, n_mem_rd_err, n_mem_wr, n_mem_wr_err, n_rsp_err,
                     n_data_checked, n_data_skipped, n_mismatch,
                     n_flush, n_flush_err, n_mem_checks, n_mem_byte_bad);
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info("SB", {"SUMMARY  ", summary()}, UVM_NONE)
    if (n_loads + n_stores == 0)
      `uvm_error("SB", "no CPU accesses were checked")
  endfunction

endclass
// ---- env/cache_cov.sv ----
`uvm_analysis_imp_decl(_cov_cpu)
`uvm_analysis_imp_decl(_cov_mem)
`uvm_analysis_imp_decl(_cov_flush)

class cache_cov extends uvm_component;

  `uvm_component_utils(cache_cov)

  uvm_analysis_imp_cov_cpu   #(cpu_item,   cache_cov) cpu_imp;
  uvm_analysis_imp_cov_mem   #(mem_item,   cache_cov) mem_imp;
  uvm_analysis_imp_cov_flush #(flush_item, cache_cov) flush_imp;

  covergroup cg_cpu with function sample(cpu_item t);
    option.per_instance = 1;
    cp_op      : coverpoint t.we      { bins load = {0}; bins store = {1}; }
    cp_outcome : coverpoint t.outcome { bins hit   = {OUT_HIT};
                                        bins clean = {OUT_CLEAN_MISS};
                                        bins dirty = {OUT_DIRTY_MISS}; }
    x_op_outcome : cross cp_op, cp_outcome;
    cp_woff    : coverpoint t.addr[OFF_W-1:BYTE_W];
    cp_wstrb   : coverpoint t.wstrb iff (t.we) {
                   bins one_byte[] = {4'b0001, 4'b0010, 4'b0100, 4'b1000};
                   bins half[]     = {4'b0011, 4'b1100};
                   bins word       = {4'b1111};
                   bins other      = default; }
    cp_err     : coverpoint t.err     { bins ok = {0}; bins error = {1}; }
    cp_rsp_bp  : coverpoint t.rsp_bp_cycles { bins none = {0}; bins some = {[1:3]}; bins many = {[4:$]}; }
  endgroup

  covergroup cg_mem with function sample(mem_item t);
    option.per_instance = 1;
    cp_kind   : coverpoint t.we  { bins refill = {0}; bins writeback = {1}; }
    cp_err    : coverpoint t.err { bins ok = {0}; bins error = {1}; }
    x_kind_err: cross cp_kind, cp_err;
    cp_req_bp : coverpoint t.req_bp_cycles { bins none = {0}; bins some = {[1:3]}; bins many = {[4:$]}; }
    cp_lat    : coverpoint t.lat_cycles    { bins fast = {[0:3]}; bins mid = {[4:10]}; bins slow = {[11:$]}; }
  endgroup

  covergroup cg_flush with function sample(flush_item t);
    option.per_instance = 1;
    cp_inv  : coverpoint t.inv  { bins clean_only = {0}; bins invalidate = {1}; }
    cp_err  : coverpoint t.err  { bins ok = {0}; bins error = {1}; }
    cp_race : coverpoint t.race { bins alone = {0}; bins cpu_waiting = {1}; }
  endgroup

  int unsigned bin_hits [string];
  string       bin_order[$];

  function new(string name, uvm_component parent);
    super.new(name, parent);
    cg_cpu   = new();
    cg_mem   = new();
    cg_flush = new();
    declare_bins();
  endfunction

  function void add_bin(string key);
    bin_order.push_back(key);
    bin_hits[key] = 0;
  endfunction

  function void bump(string key);
    if (!bin_hits.exists(key)) begin
      `uvm_error("COV", {"unknown bin ", key})
    end
    else begin
      bin_hits[key]++;
    end
  endfunction

  function void declare_bins();
    string ops[2]  = '{"load", "store"};
    string outs[3] = '{"hit", "clean", "dirty"};
    string kinds[2]= '{"refill", "writeback"};
    string errs[2] = '{"ok", "error"};
    foreach (ops[i])   add_bin({"cg_cpu,cp_op,", ops[i]});
    foreach (outs[i])  add_bin({"cg_cpu,cp_outcome,", outs[i]});
    foreach (ops[i]) foreach (outs[j]) add_bin({"cg_cpu,x_op_outcome,", ops[i], "_", outs[j]});
    for (int w = 0; w < WPL; w++) add_bin($sformatf("cg_cpu,cp_woff,%0d", w));
    add_bin("cg_cpu,cp_wstrb,one_byte_0001"); add_bin("cg_cpu,cp_wstrb,one_byte_0010");
    add_bin("cg_cpu,cp_wstrb,one_byte_0100"); add_bin("cg_cpu,cp_wstrb,one_byte_1000");
    add_bin("cg_cpu,cp_wstrb,half_0011");     add_bin("cg_cpu,cp_wstrb,half_1100");
    add_bin("cg_cpu,cp_wstrb,word_1111");
    foreach (errs[i])  add_bin({"cg_cpu,cp_err,", errs[i]});
    add_bin("cg_cpu,cp_rsp_bp,none"); add_bin("cg_cpu,cp_rsp_bp,some"); add_bin("cg_cpu,cp_rsp_bp,many");
    foreach (kinds[i]) add_bin({"cg_mem,cp_kind,", kinds[i]});
    foreach (errs[i])  add_bin({"cg_mem,cp_err,", errs[i]});
    foreach (kinds[i]) foreach (errs[j]) add_bin({"cg_mem,x_kind_err,", kinds[i], "_", errs[j]});
    add_bin("cg_mem,cp_req_bp,none"); add_bin("cg_mem,cp_req_bp,some"); add_bin("cg_mem,cp_req_bp,many");
    add_bin("cg_mem,cp_lat,fast");    add_bin("cg_mem,cp_lat,mid");     add_bin("cg_mem,cp_lat,slow");
    add_bin("cg_flush,cp_inv,clean_only"); add_bin("cg_flush,cp_inv,invalidate");
    foreach (errs[i])  add_bin({"cg_flush,cp_err,", errs[i]});
    add_bin("cg_flush,cp_race,alone"); add_bin("cg_flush,cp_race,cpu_waiting");
  endfunction

  function string range3(int unsigned v, int unsigned lo_max, int unsigned mid_max,
                         string a, string b, string c);
    if (v <= lo_max)  return a;
    if (v <= mid_max) return b;
    return c;
  endfunction

  function void count_cpu(cpu_item t);
    string op, out;
    op  = t.we ? "store" : "load";
    out = (t.outcome == OUT_HIT) ? "hit" : (t.outcome == OUT_CLEAN_MISS) ? "clean" : "dirty";
    bump({"cg_cpu,cp_op,", op});
    bump({"cg_cpu,cp_outcome,", out});
    bump({"cg_cpu,x_op_outcome,", op, "_", out});
    bump($sformatf("cg_cpu,cp_woff,%0d", t.addr[OFF_W-1:BYTE_W]));
    if (t.we) begin
      case (t.wstrb)
        4'b0001, 4'b0010, 4'b0100, 4'b1000: bump($sformatf("cg_cpu,cp_wstrb,one_byte_%b", t.wstrb));
        4'b0011, 4'b1100:                   bump($sformatf("cg_cpu,cp_wstrb,half_%b", t.wstrb));
        4'b1111:                            bump("cg_cpu,cp_wstrb,word_1111");
        default: ;
      endcase
    end
    bump({"cg_cpu,cp_err,", t.err ? "error" : "ok"});
    bump({"cg_cpu,cp_rsp_bp,", (t.rsp_bp_cycles == 0) ? "none" : (t.rsp_bp_cycles <= 3) ? "some" : "many"});
  endfunction

  function void count_mem(mem_item t);
    string kind, e;
    kind = t.we  ? "writeback" : "refill";
    e    = t.err ? "error" : "ok";
    bump({"cg_mem,cp_kind,", kind});
    bump({"cg_mem,cp_err,", e});
    bump({"cg_mem,x_kind_err,", kind, "_", e});
    bump({"cg_mem,cp_req_bp,", (t.req_bp_cycles == 0) ? "none" : (t.req_bp_cycles <= 3) ? "some" : "many"});
    bump({"cg_mem,cp_lat,", range3(t.lat_cycles, 3, 10, "fast", "mid", "slow")});
  endfunction

  function void count_flush(flush_item t);
    bump({"cg_flush,cp_inv,",  t.inv  ? "invalidate"  : "clean_only"});
    bump({"cg_flush,cp_err,",  t.err  ? "error"       : "ok"});
    bump({"cg_flush,cp_race,", t.race ? "cpu_waiting" : "alone"});
  endfunction

  function void write_csv();
    int    fd;
    string fname, tname;
    tname = uvm_root::get().get_child("uvm_test_top").get_type_name();
    fname = {"cov_", tname, run_suffix(), ".csv"};
    fd    = $fopen(fname, "w");
    if (fd == 0) begin
      `uvm_warning("COV", {"could not write ", fname})
      return;
    end
    $fdisplay(fd, "group,coverpoint,bin,hits");
    foreach (bin_order[i]) $fdisplay(fd, "%s,%0d", bin_order[i], bin_hits[bin_order[i]]);
    $fclose(fd);
    `uvm_info("COV", {"wrote ", fname}, UVM_NONE)
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    cpu_imp   = new("cpu_imp",   this);
    mem_imp   = new("mem_imp",   this);
    flush_imp = new("flush_imp", this);
  endfunction

  function void write_cov_cpu  (cpu_item   t); cg_cpu.sample(t);   count_cpu(t);   endfunction
  function void write_cov_mem  (mem_item   t); cg_mem.sample(t);   count_mem(t);   endfunction
  function void write_cov_flush(flush_item t); cg_flush.sample(t); count_flush(t); endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info("COV", $sformatf("coverage: cpu=%0.1f%%  mem=%0.1f%%  flush=%0.1f%%",
                               cg_cpu.get_inst_coverage(), cg_mem.get_inst_coverage(),
                               cg_flush.get_inst_coverage()), UVM_NONE)
    write_csv();
  endfunction

endclass
