class cache_vseqr extends uvm_sequencer;

  `uvm_component_utils(cache_vseqr)

  cpu_seqr          cpu_sqr;
  flush_seqr        flush_sqr;
  mem_seqr          mem_sqr;
  cache_cfg         cfg;
